# GENERATED by `npx ray gen` from implementation/physics.ray - do not edit
#
# THE RUNTIME the emitted classes stand on (physics.R): R's own objects, and what the recognised classes (N, String,
# Array, boolean) and the operators of Ray are in R.
#
# A Ray class is a class generator, as R6 and Reference Classes have them: `Hole$new(x = 9, y = 15)` makes one, and
# `Medium$GATHER` / `Expr$simplify(e)` are its statics. An object is an environment - R's own reference object - and
# every member is one of its bindings, reached with `$`: a field is a binding (one with a default is made on first
# read, by an active binding that then steps aside), a member without parameters is an active binding (`medium$seed`
# runs it, as a getter does), a method a function bound to the object (`medium$add(h)`). The class a member comes
# from is the nearest one declaring it, as `contains =` does it. Reference Classes do the same, but every `$` on one is
# an S4 dispatch (3-5 us here, against 0.05 us for an environment's own `$`), which the medium cannot afford.
#
# A Ray list is shared by everyone holding it (a push is seen by all), so it is an environment around an R vector or
# list (`.v`): numbers are held as a double vector where they are all numbers. Ray counts from 0; `elem` and `set_at`
# are the only places that add the 1. A list Ray only reads (a theory's rules) is a plain R list.

RT_TOP <- environment()
true <- TRUE
false <- FALSE
CONTINUE <- quote(.continue)

# --- classes and objects -----------------------------------------------------------------------------
CLASSES <- new.env(parent = emptyenv())
THEORIES <- new.env(parent = emptyenv())

#' a class: its generator, filled by `define` with the members it declares (`field`, `getter`, `method`, `statik`,
#' `static_field`); the object's own bindings are laid out when the first one is made
ray_class <- function(name, parent, define) {
  # declaring is quick uncompiled: its members are compiled when the class is first used
  jit <- compiler::enableJIT(0)
  on.exit(compiler::enableJIT(jit))
  g <- new.env(parent = emptyenv())
  g$.name <- name
  g$.parent <- parent
  g$.own <- list()
  g$.order <- character()
  g$.sown <- list()
  define(g)
  # the statics: its own, bound to the generator (`this` in a static is the class), and its parents' reached through them
  m <- new.env(parent = RT_TOP)
  m$self <- g
  snames <- names(g$.sown)
  for (n in snames) {
    s <- g$.sown[[n]]
    f <- s$fn
    environment(f) <- m
    if (s$kind == "field") makeActiveBinding(n, settle_binding(f, n, g), g)
    else if (s$kind == "getter") makeActiveBinding(n, getter_binding(f, n, g), g)
    else assign(n, f, envir = g)
  }
  if (!is.null(parent)) for (n in parent$.snames) if (!(n %in% snames)) makeActiveBinding(n, delegate_binding(parent, n), g)
  g$.snames <- unique(c(if (is.null(parent)) character() else parent$.snames, snames))
  g$new <- function(...) ray_new(g, ...)
  assign(name, g, envir = CLASSES)
  g
}
field <- function(cl, n, d) { cl$.own[[n]] <- list(kind = "field", fn = d); cl$.order <- c(cl$.order, n); invisible(cl) }
getter <- function(cl, n, f) { cl$.own[[n]] <- list(kind = "getter", fn = f); invisible(cl) }
method <- function(cl, n, f) { cl$.own[[n]] <- list(kind = "method", fn = f); invisible(cl) }
statik <- function(cl, n, f) { cl$.sown[[n]] <- list(kind = "method", fn = f); invisible(cl) }
static_getter <- function(cl, n, f) { cl$.sown[[n]] <- list(kind = "getter", fn = f); invisible(cl) }
static_field <- function(cl, n, f) { cl$.sown[[n]] <- list(kind = "field", fn = f); invisible(cl) }

#' a value made on first read, after which the binding is a plain one; written first, it is simply what was written
settle_binding <- function(f, n, e) {
  force(f); force(n); force(e)
  function(v) {
    rm(list = n, envir = e)
    val <- if (missing(v)) f() else v
    assign(n, val, envir = e)
    val
  }
}
#' a member without parameters: read, it runs; written, what is written stands in its place (as a slot shadows a getter)
getter_binding <- function(f, n, e) {
  force(f); force(n); force(e)
  function(v) {
    if (missing(v)) return(f())
    rm(list = n, envir = e)
    assign(n, v, envir = e)
  }
}
#' a static a class has from its parent: the parent's own, read and written there
delegate_binding <- function(parent, n) { force(parent); force(n); function(v) if (missing(v)) parent[[n]] else assign(n, v, envir = parent) }

cmp <- function(f) if (is.function(f)) tryCatch(compiler::cmpfun(f), error = function(e) f) else f
#' the members of a class's objects, parents' first and the nearest declaration deciding, laid out once and compiled
ray_layout <- function(g) {
  chain <- list()
  k <- g
  while (!is.null(k)) { chain <- c(list(k), chain); k <- k$.parent }
  all <- list()
  order <- character()
  for (k in chain) { for (n in names(k$.own)) all[[n]] <- k$.own[[n]]; order <- c(order, k$.order) }
  L <- list(methods = list(), consts = list(), nones = character(), getters = list(), lazies = list(), order = order, names = names(all))
  for (n in names(all)) {
    a <- all[[n]]
    f <- a$fn
    if (a$kind == "method") L$methods[[n]] <- cmp(f)
    else if (a$kind == "getter") L$getters[[n]] <- cmp(f)
    else if (is.null(f)) L$nones <- c(L$nones, n)
    else {
      b <- body(f)
      if (is.atomic(b) && length(b) == 1) L$consts[n] <- list(b) else L$lazies[[n]] <- cmp(f)
    }
  }
  g$.eq <- "equals" %in% c(names(L$methods), names(L$getters))
  g$.L <- L
  L
}
#' `Class(x: 1, ...)`: `Class$new(x = 1, ...)` - the named fields set, the rest by position in the order they are declared
ray_new <- function(g, ...) {
  L <- g$.L
  if (is.null(L)) L <- ray_layout(g)
  o <- new.env(parent = emptyenv())
  attr(o, "ray") <- g
  m <- new.env(parent = RT_TOP)
  m$self <- o
  ms <- L$methods
  for (n in names(ms)) { f <- ms[[n]]; environment(f) <- m; assign(n, f, envir = o) }
  if (length(L$consts)) list2env(L$consts, envir = o)
  for (n in L$nones) assign(n, NULL, envir = o)
  gs <- L$getters
  for (n in names(gs)) { f <- gs[[n]]; environment(f) <- m; makeActiveBinding(n, getter_binding(f, n, o), o) }
  ls <- L$lazies
  for (n in names(ls)) { f <- ls[[n]]; environment(f) <- m; makeActiveBinding(n, settle_binding(f, n, o), o) }
  a <- list(...)
  if (length(a)) {
    nms <- names(a)
    if (is.null(nms)) nms <- character(length(a))
    positional <- 0
    for (i in seq_along(a)) {
      if (nzchar(nms[i])) assign(nms[i], a[[i]], envir = o)
      else {
        positional <- positional + 1
        if (positional <= length(L$order)) assign(L$order[positional], a[[i]], envir = o)
      }
    }
  }
  o
}
#' a class by its name (`Boundary.Terminal` by its own), or a theory by its
K <- function(name) {
  v <- THEORIES[[name]]
  if (!is.null(v)) return(v)
  v <- CLASSES[[name]]
  if (!is.null(v)) return(v)
  n <- sub(".*\\.", "", name)
  v <- THEORIES[[n]]
  if (!is.null(v)) return(v)
  v <- CLASSES[[n]]
  if (is.null(v)) stop(paste0("no class ", name, " in this package"))
  v
}
#' what every class stands on - and, made bare, a map: `{}` is `Node$new()`, whose keys are its bindings
Node <- ray_class("Node", NULL, function(cl) NULL)
make <- function(.K, ...) (if (is.environment(.K)) .K else K(.K))$new(...)
class_of <- function(x) if (is.environment(x)) attr(x, "ray", exact = TRUE) else NULL

#' a theory: its class made once, its rules and theorems - data to read, in the order they are written - kept on it
theory <- function(g) {
  o <- g$new()
  assign(g$.name, o, envir = THEORIES)
  chain <- list()
  k <- g
  while (!is.null(k)) { chain <- c(list(k), chain); k <- k$.parent }
  own <- unique(unlist(lapply(chain, function(k) names(k$.sown))))
  rules <- Filter(Negate(is.null), lapply(own[startsWith(own, "rule ")], function(n) { r <- g[[n]]; class(r) <- "ray_rule"; r }))
  theorems <- lapply(own[startsWith(own, "theorem ")], function(n) g[[n]])
  assign("rules", rules, envir = o)
  assign("theorems", theorems, envir = o)
  o
}
#' a rule, as it prints: its label, name and rate, what it runs over, and its source
format.ray_rule <- function(x, ...) {
  rate <- .subset2(x, "rate")
  sprintf("rule %s \"%s\"%s over %s%s", .subset2(x, "id"), .subset2(x, "name"), if (is.null(rate)) "" else paste0(" | ", rate), .subset2(x, "over"), if (isTRUE(.subset2(x, "single"))) " (one at a time)" else "")
}
print.ray_rule <- function(x, ...) { cat(format(x), "\n", .subset2(x, "source"), "\n", sep = ""); invisible(x) }
#' a share of a term: its source, and the program that reads it at the symbols
at <- function(source, f) Node$new(source = source, at = function(s = NULL, ...) f(s))
#' a top-level definition: made on first read
lazy_constant <- function(f) {
  made <- FALSE
  v <- NULL
  function() {
    if (!made) { made <<- TRUE; v <<- f() }
    v
  }
}

# --- members where Ray reaches them by a name it computes -----------------------------------------------
#' `x[name]` on an object: its member of that name (None where it has none)
mem <- function(t, n) {
  if (!is.environment(t)) return(NULL)
  if (inherits(t, "ray_many")) return(collapse(lapply(.subset2(t, ".i"), function(x) mem(x, n))))
  get0(n, envir = t, inherits = FALSE)
}
#' `x.name = v`, and `x[name] = v` on an object
.set <- function(t, n, v) {
  force(v)
  if (!is.environment(t)) stop(paste0("no member ", n, " to set on ", text_of(t)))
  if (inherits(t, "ray_many")) for (x in .subset2(t, ".i")) .set(x, n, v)
  else assign(n, v, envir = t)
  invisible(v)
}
#' whether an object has a member of this name
has <- function(t, n) is.environment(t) && exists(n, envir = t, inherits = FALSE)
choose_ <- function(t, name) mem(t, paste0("choose ", name))
instance_of <- function(x, c) {
  g <- class_of(x)
  k <- if (is.character(c)) K(c) else c
  while (!is.null(g)) { if (identical(g, k)) return(TRUE); g <- g$.parent }
  FALSE
}
#' a local written where it was bound, from wherever it is written: the frame that holds the name (R's `<-` would make a new one)
.w <- function(nm, v) {
  force(v)
  start <- parent.frame()
  e <- start
  while (!exists(nm, envir = e, inherits = FALSE)) {
    e <- parent.env(e)
    if (identical(e, RT_TOP) || identical(e, emptyenv())) { e <- start; break }
  }
  assign(nm, v, envir = e)
  invisible(v)
}

# --- what the language's operators are here -----------------------------------------------------
#' what counts as true: everything but None, false, 0, NaN and the empty text - as in TypeScript
truthy <- function(x) {
  if (is.logical(x)) return(length(x) == 1L && !is.na(x) && x)
  if (is.null(x)) return(FALSE)
  if (is.double(x)) return(!is.na(x) && x != 0)
  if (is.character(x)) return(nzchar(x))
  if (is.numeric(x)) return(!is.na(x) && x != 0)
  TRUE
}
and_ <- function(a, b) if (truthy(a)) b else a
or_ <- function(a, b) if (truthy(a)) a else b
or_else <- function(a, b) if (is.null(a)) b else a
num <- function(x) {
  if (is.double(x)) return(x)
  if (is.null(x)) return(0)
  if (is.logical(x)) return(if (isTRUE(x)) 1 else 0)
  if (is.numeric(x)) return(as.double(x))
  NaN
}
arith <- function(a) is.null(a) || is.numeric(a) || is.logical(a)
eq <- function(a, b) {
  if (is.double(a)) return(is.double(b) && length(b) == 1L && !is.na(a == b) && a == b)
  if (is.environment(a)) {
    if (identical(a, b)) return(TRUE)
    if (is.null(b)) return(FALSE)
    if (inherits(a, "ray_many")) { for (x in .subset2(a, ".i")) if (!eq(x, b)) return(FALSE); return(TRUE) }
    x <- a$.v
    if (!is.null(x)) return(is_list(b) && same_items(x, items(b)))
    g <- attr(a, "ray", exact = TRUE)
    if (!is.null(g) && isTRUE(g$.eq)) return(truthy(a$equals(b)))
    return(FALSE)
  }
  if (is.null(a)) return(is.null(b))
  if (is.null(b)) return(FALSE)
  if (is.character(a)) return(is.character(b) && a == b)
  if (is.logical(a)) return(is.logical(b) && identical(a, b))
  if (is.list(a)) return(is_list(b) && same_items(a, items(b)))
  if (is.numeric(a)) return(is.numeric(b) && isTRUE(a == b))
  identical(a, b)
}
same_items <- function(x, y) {
  if (length(x) != length(y)) return(FALSE)
  for (i in seq_along(x)) if (!eq(x[[i]], y[[i]])) return(FALSE)
  TRUE
}
`%||%` <- function(a, b) if (is.null(a)) b else a
#' text joined: what an interpolated text is made of
`%+%` <- function(a, b) paste0(a, b)
lt <- function(a, b) if (is.double(a) && is.double(b)) a < b else if (arith(a)) num(a) < num(b) else if (is.character(a)) a < b else a$lt(b)
le <- function(a, b) if (is.double(a) && is.double(b)) a <= b else if (arith(a)) num(a) <= num(b) else if (is.character(a)) a <= b else a$le(b)
gt <- function(a, b) if (is.double(a) && is.double(b)) a > b else if (arith(a)) num(a) > num(b) else if (is.character(a)) a > b else a$gt(b)
ge <- function(a, b) if (is.double(a) && is.double(b)) a >= b else if (arith(a)) num(a) >= num(b) else if (is.character(a)) a >= b else a$ge(b)
r_add <- function(a, b) {
  if (is.double(a) && is.double(b)) return(a + b)
  if (is.character(a)) return(paste0(a, text_of(b)))
  if (arith(a)) { if (is.character(b)) return(paste0(text_of(a), b)); return(num(a) + num(b)) }
  a$plus(b)
}
r_sub <- function(a, b) if (is.double(a) && is.double(b)) a - b else if (arith(a)) num(a) - num(b) else a$minus(b)
r_mul <- function(a, b) if (is.double(a) && is.double(b)) a * b else if (arith(a)) num(a) * num(b) else a$times(b)
#' a number over nothing is nothing where it is nothing itself, and infinite otherwise - as in TypeScript
r_div <- function(a, b) {
  if (is.double(a) && is.double(b) && b != 0) return(a / b)
  if (!arith(a)) return(a$over(b))
  x <- num(a); y <- num(b)
  if (y == 0 && !is.na(x) && x == 0) 0 else x / y
}
#' the remainder with the sign of what is divided, as TypeScript's `%`
r_mod <- function(a, b) {
  if (is.double(a) && is.double(b) && b > 0 && a >= 0 && is.finite(a)) return(a %% b)
  if (!arith(a)) return(a$mod(b))
  x <- num(a); y <- num(b)
  if (y == 0 || is.infinite(x) || is.na(x) || is.na(y)) return(NaN)
  if (is.infinite(y)) return(x)
  r <- x %% y
  if (r != 0 && (r < 0) != (x < 0)) r - y else r
}
neg <- function(a) if (arith(a)) -num(a) else a$negated
r_pow <- function(a, b) if (arith(a)) num(a)^num(b) else a$pow(b)

#' a number as TypeScript writes it: the shortest text that reads back as the same number
js_num <- function(x) {
  if (is.nan(x) || is.na(x)) return("NaN")
  if (is.infinite(x)) return(if (x > 0) "Infinity" else "-Infinity")
  if (x == 0) return("0")
  if (x == trunc(x) && abs(x) < 1e21) return(sprintf("%.0f", x))
  s <- NULL
  for (d in 1:17) { s <- sprintf(paste0("%.", d - 1, "e"), x); if (as.numeric(s) == x) break }
  neg_ <- x < 0
  m <- sub("e.*$", "", sub("^-", "", s))
  e <- as.integer(sub("^.*e", "", s))
  digits <- sub("0+$", "", gsub(".", "", m, fixed = TRUE))
  if (!nzchar(digits)) digits <- "0"
  k <- nchar(digits)
  n <- e + 1
  out <- if (k <= n && n <= 21) paste0(digits, strrep("0", n - k))
    else if (0 < n && n <= 21) paste0(substr(digits, 1, n), ".", substr(digits, n + 1, k))
    else if (-6 < n && n <= 0) paste0("0.", strrep("0", -n), digits)
    else {
      ex <- n - 1
      paste0(substr(digits, 1, 1), if (k > 1) paste0(".", substr(digits, 2, k)) else "", "e", if (ex >= 0) "+" else "-", abs(ex))
    }
  if (neg_) paste0("-", out) else out
}
#' a value as text, as the bootstrap writes it: whole numbers without a point, a list its items joined by commas
text_of <- function(x) {
  if (is.character(x)) return(x)
  if (is.double(x)) return(if (length(x) == 1) js_num(x) else paste(vapply(x, js_num, ""), collapse = ","))
  if (is.null(x)) return("null")
  if (is.logical(x)) return(if (isTRUE(x)) "true" else "false")
  if (is.environment(x)) {
    if (inherits(x, "ray_many")) return(paste(vapply(.subset2(x, ".i"), text_of, ""), collapse = ","))
    v <- x$.v
    if (!is.null(v)) return(paste(vapply(v, text_of, ""), collapse = ","))
    if (exists("toString", envir = x, inherits = FALSE)) { s <- x[["toString"]]; return(text_of(if (is.function(s)) s() else s)) }
    g <- attr(x, "ray", exact = TRUE)
    if (!is.null(g)) return(g$.name)
    if (!is.null(x$.name)) return(x$.name)
  }
  if (is.list(x)) return(paste(vapply(x, text_of, ""), collapse = ","))
  if (is.numeric(x)) return(js_num(as.double(x)))
  if (is.function(x)) return("function")
  paste(as.character(x), collapse = ",")
}

# --- lists and text -------------------------------------------------------------------------------
as_list <- function(v) { l <- new.env(parent = emptyenv()); l$.v <- v; l }
#' `[a, b]`: a list, shared by everyone holding it
lst <- function(...) as_list(list(...))
is_list <- function(x) if (is.environment(x)) !inherits(x, "ray_many") && !is.null(x$.v) else is.list(x)
#' what a list, a Many or a text holds, as an R vector or list (a copy: what it is iterated over is not changed by what the loop does)
items <- function(xs) {
  if (is.environment(xs)) {
    if (inherits(xs, "ray_many")) return(.subset2(xs, ".i"))
    v <- xs$.v
    if (!is.null(v)) return(v)
  }
  if (is.list(xs)) return(xs)
  if (is.character(xs)) return(as.list(strsplit(xs, "")[[1]]))
  if (is.null(xs)) return(list())
  stop(paste0("not a list: ", text_of(xs)))
}
len <- function(xs) {
  if (is.environment(xs)) {
    v <- xs$.v
    if (!is.null(v)) return(as.double(length(v)))
    if (inherits(xs, "ray_many")) return(as.double(length(.subset2(xs, ".i"))))
    return(xs$length)
  }
  if (is.character(xs)) return(as.double(nchar(xs)))
  if (is.list(xs)) return(as.double(length(xs)))
  if (is.null(xs)) stop("no member length on None")
  stop(paste0("no member length on ", typeof(xs)))
}
#' `x[k]`: an element of a list (negative from the end), or a member by its name
elem <- function(t, k) {
  if (is.environment(t)) {
    v <- t$.v
    if (!is.null(v)) {
      if (!is.double(k)) { if (is.null(k) || is.character(k)) return(NULL); k <- num(k) }
      n <- length(v)
      if (k < 0) k <- k + n
      if (k >= 0 && k < n) return(.subset2(v, k + 1))
      return(NULL)
    }
    if (inherits(t, "ray_many")) return(collapse(lapply(.subset2(t, ".i"), function(x) elem(x, k))))
    if (is.null(k)) return(NULL)
    return(get0(key_(k), envir = t, inherits = FALSE))
  }
  if (is.list(t)) {
    if (!is.numeric(k)) return(NULL)
    n <- length(t)
    if (k < 0) k <- k + n
    return(if (k >= 0 && k < n) t[[k + 1]] else NULL)
  }
  if (is.character(t)) {
    if (!is.numeric(k)) return(NULL)
    n <- nchar(t)
    if (k < 0) k <- k + n
    if (k >= 0 && k < n) return(substr(t, k + 1, k + 1))
    return(NULL)
  }
  NULL
}
#' `x[k] = v`. The list is taken out of its environment first, so that R changes it in place instead of copying it;
#' numbers stay a double vector while only numbers are written
set_at <- function(t, k, v) {
  force(v)
  if (is.environment(t) && !inherits(t, "ray_many")) {
    l <- t$.v
    if (!is.null(l)) {
      i <- num(k) + 1
      t$.v <- NULL
      if (is.double(l) && is.double(v) && length(v) == 1L) l[i] <- v
      else { if (!is.list(l)) l <- as.list(l); l[i] <- list(v) }
      t$.v <- l
      return(v)
    }
  }
  .set(t, key_(k), v)
}
#' a key of a map as a name: R names no variable "", so the empty key is kept under one R never writes
key_ <- function(k) { k <- if (is.character(k)) k else text_of(k); if (nzchar(k)) k else "\001" }
push <- function(xs, x) {
  force(x)
  l <- xs$.v
  xs$.v <- NULL
  if (is.double(l) && is.double(x) && length(x) == 1L) l[length(l) + 1] <- x
  else { if (!is.list(l)) l <- as.list(l); l[length(l) + 1] <- list(x) }
  xs$.v <- l
  xs
}
filt <- function(xs, f, ...) {
  if (inherits(xs, "ray_many")) return(many_of(Filter(function(x) truthy(f(x)), .subset2(xs, ".i"))))
  as_list(Filter(function(x) truthy(f(x)), items(xs)))
}
rng <- function(n) { k <- ceiling(num(n)); as_list(if (k > 0) seq_len(k) - 1 else numeric(0)) }
filled <- function(n, v) {
  k <- max(0, ceiling(num(n)))
  as_list(if (is.double(v) && length(v) == 1L) rep(v, k) else rep(list(v), k))
}
#' a block taken apart by `for`: each turn a call of its own; a turn that returned hands out what it returned (in a list) and stops the loop
for_each <- function(xs, f) {
  for (x in items(xs)) { r <- f(x); if (!is.symbol(r)) return(list(r)) }
  NULL
}
for_range <- function(n, f) {
  k <- ceiling(num(n))
  if (k > 0) for (i in seq_len(k) - 1) { r <- f(i); if (!is.symbol(r)) return(list(r)) }
  NULL
}
contains <- function(xs, x) {
  if (is.character(xs)) return(grepl(text_of(x), xs, fixed = TRUE))
  for (y in items(xs)) if (eq(y, x)) return(TRUE)
  FALSE
}
index_of <- function(xs, x) {
  if (is.character(xs)) { i <- regexpr(text_of(x), xs, fixed = TRUE)[1]; return(if (i < 0) NULL else as.double(i - 1)) }
  l <- items(xs)
  for (i in seq_along(l)) if (eq(l[[i]], x)) return(as.double(i - 1))
  NULL
}
first <- function(xs) { if (is.character(xs)) return(if (nzchar(xs)) substr(xs, 1, 1) else NULL); l <- items(xs); if (length(l)) l[[1]] else NULL }
last <- function(xs) { if (is.character(xs)) { n <- nchar(xs); return(if (n) substr(xs, n, n) else NULL) }; l <- items(xs); if (length(l)) l[[length(l)]] else NULL }
join <- function(xs, sep) paste(vapply(items(xs), text_of, ""), collapse = text_of(sep))
#' a text in double quotes, as JSON writes it
quoted <- function(x) {
  s <- text_of(x)
  s <- gsub("\\", "\\\\", s, fixed = TRUE)
  s <- gsub("\"", "\\\"", s, fixed = TRUE)
  s <- gsub("\n", "\\n", s, fixed = TRUE)
  s <- gsub("\r", "\\r", s, fixed = TRUE)
  s <- gsub("\t", "\\t", s, fixed = TRUE)
  paste0("\"", s, "\"")
}
most <- function(xs, key) {
  l <- items(xs)
  best <- NULL; at_ <- -1; bk <- -Inf
  for (i in seq_along(l)) { k <- num(key(l[[i]])); if (is.null(best) || k > bk) { best <- l[[i]]; at_ <- i - 1; bk <- k } }
  if (is.null(best)) NULL else lst(best, as.double(at_))
}
sorted_by <- function(xs, key) {
  l <- items(xs)
  if (!length(l)) return(as_list(list()))
  k <- vapply(l, function(x) num(key(x)), 0)
  as_list(l[order(k, seq_along(l), method = "radix")])
}
#' a sum taken in order, one term after another, as every other language takes it (R's `sum` carries more bits)
summed <- function(xs) { s <- 0; for (x in items(xs)) s <- s + num(x); s }
fail <- function(says) stop(text_of(says))
codepoints <- function(s) as_list(as.double(utf8ToInt(s)))
from_codepoints <- function(xs) intToUtf8(vapply(items(xs), function(c) as.integer(num(c)), 0L))
blank <- function(c) { d <- num(c); d == 32 || d == 9 || d == 10 || d == 13 }
number <- function(s) { v <- suppressWarnings(as.numeric(trimws(text_of(s)))); if (is.na(v)) NaN else v }

#' a member Ray knows on a list, a text or a number - and any object's own member of that name otherwise (`Expr.split(e, name)`)
core <- function(x) !is.environment(x) || inherits(x, "ray_many") || !is.null(x$.v)
m_push <- function(xs, ...) if (core(xs)) push(xs, ..1) else xs$push(...)
m_chars <- function(xs) if (is.character(xs)) codepoints(xs) else xs$chars
m_pop <- function(xs) {
  if (!core(xs)) return(xs$pop)
  l <- xs$.v
  n <- length(l)
  if (!n) return(NULL)
  xs$.v <- NULL
  x <- l[[n]]
  length(l) <- n - 1
  xs$.v <- l
  x
}
m_map <- function(xs, ...) { if (!core(xs)) return(xs$map(...)); f <- ..1; as_list(lapply(items(xs), function(x) f(x))) }
m_for <- function(xs, ...) { if (!core(xs)) return(xs$`for`(...)); f <- ..1; for (x in items(xs)) f(x); NULL }
m_some <- function(xs, ...) { if (!core(xs)) return(xs$some(...)); f <- ..1; for (x in items(xs)) if (truthy(f(x))) return(TRUE); FALSE }
m_every <- function(xs, ...) { if (!core(xs)) return(xs$every(...)); f <- ..1; for (x in items(xs)) if (!truthy(f(x))) return(FALSE); TRUE }
m_reduce <- function(xs, ...) { if (!core(xs)) return(xs$reduce(...)); acc <- ..1; f <- ..2; for (x in items(xs)) acc <- f(acc, x); acc }
m_starts_with <- function(xs, ...) if (core(xs)) startsWith(xs, text_of(..1)) else xs$starts_with(...)
m_ends_with <- function(xs, ...) if (core(xs)) endsWith(xs, text_of(..1)) else xs$ends_with(...)
m_replace <- function(xs, ...) if (core(xs)) gsub(text_of(..1), text_of(..2), xs, fixed = TRUE) else xs$replace(...)
m_split <- function(xs, ...) {
  if (!core(xs)) return(xs$split(...))
  sep <- text_of(..1)
  if (!nzchar(sep)) return(as_list(items(xs)))
  as_list(as.list(strsplit(paste0(xs, sep), sep, fixed = TRUE)[[1]]))
}
m_trim <- function(xs) if (core(xs)) trimws(xs) else xs$trim
m_upper <- function(xs) if (core(xs)) toupper(xs) else xs$upper
m_lower <- function(xs) if (core(xs)) tolower(xs) else xs$lower
m_lines <- function(xs) if (core(xs)) m_split(xs, "\n") else xs$lines
m_contains <- function(xs, ...) if (core(xs)) contains(xs, ..1) else xs$contains(...)
m_index_of <- function(xs, ...) if (core(xs)) index_of(xs, ..1) else xs$index_of(...)
m_join <- function(xs, ...) if (core(xs)) join(xs, ..1) else xs$join(...)
m_first <- function(xs) if (core(xs)) first(xs) else xs$first
m_last <- function(xs) if (core(xs)) last(xs) else xs$last
m_empty <- function(xs) if (core(xs)) len(xs) == 0 else xs$empty
m_take <- function(xs, ...) {
  if (!core(xs)) return(xs$take(...))
  k <- num(..1)
  if (is.character(xs)) return(substr(xs, 1, max(0, k)))
  l <- items(xs)
  as_list(l[seq_len(max(0, min(k, length(l))))])
}
m_drop <- function(xs, ...) {
  if (!core(xs)) return(xs$drop(...))
  k <- num(..1)
  if (is.character(xs)) return(substr(xs, max(0, k) + 1, nchar(xs)))
  l <- items(xs)
  k <- max(0, min(k, length(l)))
  as_list(if (k >= length(l)) l[0] else l[(k + 1):length(l)])
}
m_rest <- function(xs) if (core(xs)) m_drop(xs, 1) else xs$rest
m_concat <- function(xs, ...) {
  if (!core(xs)) return(xs$concat(...))
  ys <- ..1
  if (is.character(xs)) return(paste0(xs, text_of(ys)))
  a <- items(xs); b <- items(ys)
  as_list(if (is.double(a) && is.double(b)) c(a, b) else c(as.list(a), as.list(b)))
}
m_reverse <- function(xs) {
  if (!core(xs)) return(xs$reverse)
  if (is.character(xs)) return(intToUtf8(rev(utf8ToInt(xs))))
  as_list(rev(items(xs)))
}
m_sum <- function(xs) if (core(xs)) summed(xs) else xs$sum
m_most <- function(xs, ...) if (core(xs)) most(xs, ..1) else xs$most(...)
m_sorted_by <- function(xs, ...) if (core(xs)) sorted_by(xs, ..1) else xs$sorted_by(...)
m_each <- function(xs) if (core(xs)) many_of(as.list(items(xs))) else xs$each
m_sqrt <- function(x) if (arith(x)) { v <- num(x); if (v < 0 || is.na(v)) NaN else sqrt(v) } else x$sqrt
m_floor <- function(x) if (arith(x)) floor(num(x)) else x$floor
m_abs <- function(x) if (arith(x)) abs(num(x)) else x$abs
m_magnitude <- function(x) if (arith(x)) abs(num(x)) else x$magnitude
m_cos <- function(x) if (arith(x)) cos(num(x)) else x$cos
m_sin <- function(x) if (arith(x)) sin(num(x)) else x$sin
m_round <- function(x) if (arith(x)) floor(num(x) + 0.5) else x$round
m_ln <- function(x) if (arith(x)) { v <- num(x); if (is.na(v) || v < 0) NaN else log(v) } else x$ln
m_exp <- function(x) if (arith(x)) exp(num(x)) else x$exp
m_atan2 <- function(x, ...) if (arith(x)) atan2(num(x), num(..1)) else x$atan2(...)
m_pow <- function(x, ...) if (arith(x)) num(x)^num(..1) else x$pow(...)

# --- the Many: a superposition; members apply elementwise, equal things collapse ---------------------
many_of <- function(l) { m <- new.env(parent = emptyenv()); m$.i <- as.list(l); class(m) <- "ray_many"; m }
many <- function(xs) many_of(items(xs))
#' `x.MOVE` on many rays moves each; `x.vertex` of one point's rays is the point; a method is called on each
`$.ray_many` <- function(x, name) {
  its <- .subset2(x, ".i")
  if (startsWith(name, ".")) return(if (name == ".i") its else NULL)
  vals <- lapply(its, function(i) if (is.environment(i)) i[[name]] else NULL)
  if (length(vals) && all(vapply(vals, is.function, TRUE))) return(function(...) collapse(lapply(vals, function(f) f(...))))
  collapse(vals)
}
`$<-.ray_many` <- function(x, name, value) { for (i in .subset2(x, ".i")) assign(name, value, envir = i); x }
print.ray_many <- function(x, ...) { cat("<many of ", length(.subset2(x, ".i")), ">\n", sep = ""); invisible(x) }
collapse <- function(l) {
  if (!length(l)) return(many_of(l))
  f <- l[[1]]
  for (i in l) if (!(identical(i, f) || (is_list(i) && is_list(f) && eq(i, f)))) return(many_of(l))
  f
}
